import React, { useContext } from 'react';
import { TripContext } from '../context/TripContext';

const TripSummary = () => {
  const { families = [], expenses = [] } = useContext(TripContext);

  // Total number of people = sum of all family member counts
  const totalPeople = families.reduce((sum, fam) => sum + fam.members.length, 0);

  // Total expense
  const totalExpense = expenses.reduce((sum, exp) => sum + exp.amount, 0);

  // Per person share
  const perPersonCost = totalPeople > 0 ? totalExpense / totalPeople : 0;

  // Calculate for each family
  const owed = families.map(family => {
    const memberCount = family.members.length;
    const share = memberCount * perPersonCost;

    const paid = expenses
      .filter(exp => exp.paidBy === family.head)
      .reduce((sum, exp) => sum + exp.amount, 0);

    return {
      family: family.head,
      paid,
      share,
      balance: paid - share
    };
  });

  return (
    <div style={{ marginTop: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
      <h3>Trip Summary</h3>
      <p><strong>Total Expense:</strong> ₹{totalExpense.toFixed(2)}</p>
      <p><strong>Per Person Share:</strong> ₹{perPersonCost.toFixed(2)}</p>
      <ul style={{ marginTop: '15px' }}>
        {owed.map((o, i) => (
          <li key={i} style={{ marginBottom: '8px' }}>
            <strong>{o.family}</strong> paid ₹{o.paid.toFixed(2)}, should pay ₹{o.share.toFixed(2)} ⇒
            {o.balance > 0
              ? <span style={{ color: 'green' }}> gets ₹{o.balance.toFixed(2)}</span>
              : <span style={{ color: 'red' }}> owes ₹{(-o.balance).toFixed(2)}</span>
            }
          </li>
        ))}
      </ul>
    </div>
  );
};

export default TripSummary;
